document.addEventListener('click',e=>{const o=e.target.closest?.('[data-v26-open],[data-v26-module]');if(o){const id=o.dataset.v26Open||o.dataset.v26Module;if(READY.has(id)){queueMicrotask(()=>show(id));return}}const act=e.target.closest?.('[data-v352-act]');if(act){e.preventDefault();e.stopPropagation();act.closest('.aoV352Choice')?.querySelectorAll('[data-v352-act]').forEach(x=>x.setAttribute('aria-pressed',String(x===act)));return}if(e.target.closest?.('[data-v352-home]')){e.preventDefault();openHome();return}if(e.target.closest?.('[data-v352-close]')){e.preventDefault();close();return}if(e.target.closest?.('[data-v352-manage-intentions]')){e.preventDefault();legacyOpen('MASS_OFFER_BALT_1888');return}const a=e.target.closest?.('[data-v352-adapter]');if(a){e.preventDefault();close();const store=rt()?.store;if(a.dataset.v352Adapter==='prepare')store?.dispatch({type:'enter-prepare'});return}if(e.target.closest?.('[data-v352-clear-conf]')){e.preventDefault();base.confessionStore?.clear?.();show('CONFESSION_LAS_1911');return}},true);
